const values = $json.values || [];
const [header = [], ...rows] = values;
const columns = header.map((value) => String(value || '').trim());
const index = Object.fromEntries(columns.map((name, column) => [name, column]));
const normalized = rows.map((row, offset) => {
  const get = (name) => row[index[name]] ?? '';
  return {
    rowKey: `Modus Backlog:${offset + 2}`,
    rowNumber: offset + 2,
    title: String(get('Name')).trim(),
    issueNumber: String(get('Issue #')).trim() || null,
    category: get('Category'),
    type: get('Type'),
    product: get('Product'),
    priority: get('Priority'),
    size: get('PM/Team Est. Size'),
    assignedTo: get('Assigned To'),
    designSource: get('Design Source'),
    ready: get('Ready?'),
    blocker: get('Blocker'),
  };
}).filter((row) => row.title && ['yes', 'in refinement'].includes(String(row.ready).toLowerCase()));
const quality = normalized.filter((row) => row.ready.toLowerCase() === 'yes' && (!row.priority || !row.size || !row.designSource || row.designSource.toLowerCase() === 'tbd'));
const candidates = normalized.map((row) => ({
  ...row,
  action: row.issueNumber ? 'verify-or-enrich' : 'scaffold-after-review',
  flags: [
    !row.issueNumber && 'missing issue number',
    !row.priority && 'missing priority',
    !row.size && 'missing size',
    String(row.designSource).toLowerCase() === 'tbd' && 'design source TBD',
  ].filter(Boolean),
}));
const staticData = $getWorkflowStaticData('global');
const reviewId = `backlog-${Date.now()}`;
staticData.backlogReviews = staticData.backlogReviews || {};
staticData.backlogReviews[reviewId] = { createdAt: Date.now(), rows: candidates, quality };
return [{ json: { reviewId, candidates, quality } }];

const rows = $json.candidates || [];
const reviewId = $json.reviewId;
const widgets = rows.slice(0, 100).map((row) => ({ selectionInput: { name: 'rowKeys', type: 'CHECK_BOX', items: [{ text: `[${row.rowKey}] ${row.title} — ${row.action}${row.flags.length ? ` (${row.flags.join(', ')})` : ''}`, value: row.rowKey, selected: false }] } }));
widgets.push({ textParagraph: { text: `Quality flags: ${($json.quality || []).length}. Remaining Team-tab capacity is attached by the production workflow as read-only context. This template never assigns or reorders work.` } });
widgets.push({ buttonList: { buttons: [{ text: 'Enrich selected rows', onClick: { action: { actionMethodName: 'backlog_enrich_selected', parameters: [{ key: 'reviewId', value: reviewId }] } } }] } });
return [{ json: { reviewId, reviewCard: { cardsV2: [{ cardId: reviewId, card: { header: { title: 'Modus backlog enrichment review', subtitle: 'Human selection required' }, sections: [{ widgets }] } }] } } }];

const event = $json.body ?? $json;
const action = event.action ?? event.common?.invokedFunction ?? {};
const parameters = Object.fromEntries((action.parameters ?? []).map((p) => [p.key, p.value]));
const selected = event.common?.formInputs?.rowKeys?.stringInputs?.value ?? [];
const staticData = $getWorkflowStaticData('global');
const review = staticData.backlogReviews?.[parameters.reviewId];
if (!review) throw new Error('Backlog review not found or expired.');
const keys = new Set(selected);
const rows = review.rows.filter((row) => keys.has(row.rowKey));
return rows.map((row) => ({ json: { row, reviewId: parameters.reviewId } }));
